import subprocess, sys, base64
from pathlib import Path
FILES = {
    'tools/py/unified_server.py': b'',
    'tools/ps1/run_unified_server.ps1': b'',
    'docs/ops/unified_server.md': b'',
    'tests/smoke/test_unified_server.py': b'',
}
def run(a,cwd=None,check=True): subprocess.run(a,cwd=cwd,check=check)
def root(here):
    p=here
    for _ in range(8):
        if (p/'.git').exists(): return p
        p=p.parent
    return here
def ensure_dirs(r: Path):
    (r/'config').mkdir(exist_ok=True, parents=True)
    (r/'reports'/'ops').mkdir(exist_ok=True, parents=True)
def main():
    here = Path(__file__).resolve(); r = root(here); ensure_dirs(r)
    for rel,b in FILES.items():
        p=r/rel; p.parent.mkdir(parents=True,exist_ok=True); p.write_bytes(base64.b64decode(b))
    try: run(['git','checkout','-B','step/PA-350-unified-server'], r)
    except Exception: pass
    try: run(['git','add','-A'], r)
    except Exception: pass
    try: run(['git','commit','-m','PA-350: add unified server harness + runner + docs + smoke'], r, check=False)
    except Exception: pass
    try: run(['git','push','-u','origin','step/PA-350-unified-server'], r, check=False)
    except Exception: pass
    print('PA-350 done.')
if __name__=='__main__': main()